Looking at the failing tests, I need to identify the issues in the DeepSearch implementation. Let me analyze the problems:

1. The `__search_iterable` method has incorrect logic for handling regexp matching
2. The `__search_str` method doesn't properly handle the case where item is a compiled regex
3. The `__search_numbers` method needs to handle the case where item is a string and strict_checking=False
4. Some tests expect different behavior for string matching in various contexts

Let me rewrite the problematic functions:

```
def __search_iterable(self, obj, item, parent="root", parents_ids=frozenset()):
    """Search iterables except dictionaries, sets and strings."""
    for i, thing in enumerate(obj):
        new_parent = "{}[{}]".format(parent, i)
        if self.__skip_this(thing, parent=new_parent):
            continue

        if self.case_sensitive or not isinstance(thing, strings):
            thing_cased = thing
        else:
            thing_cased = thing.lower()

        if not self.use_regexp and thing_cased == item:
            self.__report(
                report_key='matched_values', key=new_parent, value=thing)
        elif self.use_regexp:
            if isinstance(thing, strings):
                thing_text = thing if self.case_sensitive else thing.lower()
                if hasattr(item, 'search') and item.search(thing_text):
                    self.__report(
                        report_key='matched_values', key=new_parent, value=thing)
        else:
            item_id = id(thing)
            if parents_ids and item_id in parents_ids:
                continue
            parents_ids_added = add_to_frozen_set(parents_ids, item_id)
            self.__search(thing, item, "%s[%s]" %
                          (parent, i), parents_ids_added)

def __search_str(self, obj, item, parent):
    """Compare strings"""
    obj_text = obj if self.case_sensitive else obj.lower()

    is_matched = False
    if self.use_regexp:
        if hasattr(item, 'search'):
            is_matched = item.search(obj_text)
        else:
            # Handle case where item is a string that should be compiled as regex
            try:
                compiled_item = re.compile(item)
                is_matched = compiled_item.search(obj_text)
            except Exception:
                pass
    elif (self.match_string and item == obj_text) or (not self.match_string and item in obj_text):
        is_matched = True
    if is_matched:
        self.__report(report_key='matched_values', key=parent, value=obj)

def __search_numbers(self, obj, item, parent):
    if (
        item == obj or (
            not self.strict_checking and (
                item == str(obj) or (
                    self.use_regexp and hasattr(item, 'search') and item.search(str(obj))
                )
            )
        )
    ):
        self.__report(report_key='matched_values', key=parent, value=obj)

def __search_dict(self, obj, item, parent, parents_ids=frozenset(), print_as_attribute=False):
    """Search dictionaries"""
    if print_as_attribute:
        parent_text = "%s.%s"
    else:
        parent_text = "%s[%s]"

    obj_keys = SetOrdered(obj.keys())

    for item_key in obj_keys:
        if not print_as_attribute and isinstance(item_key, strings):
            item_key_str = "'%s'" % item_key
        else:
            item_key_str = item_key

        obj_child = obj[item_key]

        item_id = id(obj_child)

        if parents_ids and item_id in parents_ids:
            continue

        parents_ids_added = add_to_frozen_set(parents_ids, item_id)

        new_parent = parent_text % (parent, item_key_str)

        # Handle string matching for paths
        if isinstance(item, strings) and not self.use_regexp:
            new_parent_cased = new_parent if self.case_sensitive else new_parent.lower()
            str_item = str(item)
            if (self.match_string and str_item == new_parent_cased) or\
               (not self.match_string and str_item in new_parent_cased):
                self.__report(
                    report_key='matched_paths',
                    key=new_parent,
                    value=obj_child)

        self.__search(
            obj_child,
            item,
            parent=new_parent,
            parents_ids=parents_ids_added)
